export function restore(raw){try{const a=JSON.parse(raw);return Array.isArray(a)?a.filter(t=>t&&typeof t.id==='string'&&typeof t.title==='string'&&typeof t.done==='boolean'&&['high','normal','low'].includes(t.priority)):[]}catch{return []}}
export function change(tasks,a){if(a.type==='add'){if(!a.title.trim())return tasks;return [...tasks,{id:(typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('')),title:a.title.trim(),done:false,priority:a.priority||'normal',created:Date.now()}]}return tasks.flatMap(t=>{if(t.id!==a.id)return[t];if(a.type==='delete')return[];if(a.type==='toggle')return[{...t,done:!t.done}];if(a.type==='edit'&&a.title.trim())return[{...t,title:a.title.trim()}];return[t]})}
export function select(tasks,filter,query){return tasks.filter(t=>(filter==='all'||filter==='active'&&!t.done||filter==='done'&&t.done||filter==='important'&&t.priority==='high'&&!t.done)&&t.title.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>Number(a.done)-Number(b.done))}
